{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Four previous reviews have assessed the quality of COVID-19 CPGs [16-18] . Two of them focused on the CPGs produced in the early phase of the pandemic. Zhao et al. evaluated CPGs for 5 different viruses, including SARS-CoV2, that have caused public health emergencies of international concern over 20 years, with search date ending February 2, 2020. Dagens et al. study focused on the early stage of the pandemic, with search date up to March 14, 2020 [1] . The third by Chiesa-Estomba et al. was limited to CPGs related to tracheostomies, and the fourth by Luo et al included CPGs on management of COVID-19 in pediatric wards [18] .However, an assessment of all the CPGs focused on the management of critically ill COVID -19 patients was lacking.",
      "reason": "The manuscript describes the current state of knowledge by citing four previous reviews and identifying the gap (lack of assessment of all CPGs focused on critically ill COVID-19 patients)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Given the extraordinary burden that the pandemic has created on the emergency and critical care units worldwide, there is an urgent need for evidence-based guidance to facilitate optimal clinical and policy decisionmaking. ... We, therefore, aimed to systematically identify the CPGs for the management of critically ill patients with COVID-19, and critically assess their quality for both clinical and methodological purposes.",
      "reason": "The authors explain the importance and need for the review due to the burden of the pandemic and the need for trustworthy guidance for clinical and policy decision-making."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Four previous reviews have assessed the quality of COVID-19 CPGs [16-18] . Two of them focused on the CPGs produced in the early phase of the pandemic. Zhao et al. evaluated CPGs for 5 different viruses, including SARS-CoV2, that have caused public health emergencies of international concern over 20 years, with search date ending February 2, 2020. Dagens et al. study focused on the early stage of the pandemic, with search date up to March 14, 2020 [1] . The third by Chiesa-Estomba et al. was limited to CPGs related to tracheostomies, and the fourth by Luo et al included CPGs on management of COVID-19 in pediatric wards [18] .",
      "reason": "The authors identify and cite previous systematic reviews and explain why their review is needed (i.e., the previous reviews were limited in scope or focused on different populations)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of clinical practice guidelines, not a review of intervention effects, so a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of clinical practice guidelines, not a review of complex interventions or delivery contexts requiring a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Objective: We aimed to systematically identify and critically assess the clinical practice guidelines (CPGs) for the management of critically ill patients with COVID-19 with the AGREE II instrument.",
      "reason": "The manuscript explicitly states the objective of the review in the abstract section."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of clinical practice guidelines (CPGs), not a review of intervention effects (e.g., a meta-analysis of clinical trials). Therefore, PICO comparisons are not applicable."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "For inclusion, CPGs had to provide specific recommendations for clinical management, diagnosis and/or treatment of critically ill patients with COVID-19. When more than one version was available, we included only the most updated version or edition of the eligible RGs.",
      "reason": "The review specifies the inclusion criteria for the clinical practice guidelines (CPGs) based on their content (recommendations for management, diagnosis, or treatment of critically ill COVID-19 patients) and versioning."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_16",
      "quote": "We had to exclude, for now, CPGs that were written in languages that were not covered by our research team (i.e., Japanese). Moreover, the assessments were conducted only on CPGs that were either published in peer review journals or posted in official websites as CPG full documents",
      "reason": "The review specifies language and publication status criteria. However, it does not explicitly state a dissemination year range for the included guidelines."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of clinical practice guidelines, not a systematic review of primary studies where exclusion based on outcome reporting is a standard methodological step."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "The table summarizes the scope of the recommendations. Each row shows the most common interventions of interest in critical patients with COVID-19 (general supportive care and therapeutic interventions). The second column displays the number of guidelines that cover each recommendation, and the following columns describes the guidelines that provide recommendations for each intervention of interest categorized as Low, Moderate or High quality according to AGREE score obtained in domain 3.",
      "reason": "The review specifies how the guidelines were grouped for synthesis (by intervention type and quality score)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "We had to exclude, for now, CPGs that were written in languages that were not covered by our research team (i.e., Japanese). Moreover, the assessments were conducted only on CPGs that were either published in peer review journals or posted in official websites as CPG full documents, without considering unpublished or supplementary material",
      "reason": "The review provides clear rationales for the restrictions on language and publication status."
    }
  ],
  "confidence": 95
}

